import { LOCKUPS } from "@/lib/logo-paths";

/**
 * The Valor Limo logo as inline SVG, drawn from lib/logo-paths.js (generated by scripts/build-logo.py).
 * variant: "primary" (Valor, the car, LIMO), "inline" (Valor over the car, for the header) or "car".
 * "Valor" takes currentColor; the car and LIMO take --color-gold (or currentColor when `mono`).
 */
export default function Logo({ variant = "primary", mono = false, title = "Valor Limo", className = "", height }) {
  const { w, h, parts } = LOCKUPS[variant];
  const gold = mono ? "currentColor" : "var(--color-gold)";
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true };
  return (
    <svg className={`logo logo-${variant} ${className}`} viewBox={`0 0 ${w} ${h}`} height={height} {...a11y}>
      {parts.map((p, i) => (
        <g
          key={i}
          fill={p.role === "ink" ? "currentColor" : gold}
          style={p.role === "ink" ? undefined : { color: gold }}
          dangerouslySetInnerHTML={{ __html: p.svg }}
        />
      ))}
    </svg>
  );
}
